//! Wolfram exact dot-product/norm replay.
//!
//! The fixture (`sonium-qa/wolfram/goldens/exact-linear-algebra-v1.json`,
//! generated by `sonium-qa/wolfram/exact_linear_algebra.wls`) carries exact
//! complex vectors with independent dot (conjugated and plain) and norm
//! references, per audit-sonium-solvers-core-20260921. The matrix-function
//! fixture (`sonium-qa/wolfram/goldens/matrix-functions-v1.json`, generated
//! by `sonium-qa/wolfram/matrix_functions.wls`) carries the adjoint
//! reference for `DenseMatrix::adjoint`.

use num_complex::Complex64;
use serde::Deserialize;
use sonium_solvers_core::blas_helpers::{dot_unconjugated, inner_product, vector_norm};
use sonium_solvers_core::dense::DenseMatrix;

const FIXTURE: &str =
    include_str!("../../../../../crates/sonium-qa/wolfram/goldens/exact-linear-algebra-v1.json");
const MATRIX_FUNCTIONS: &str =
    include_str!("../../../../../crates/sonium-qa/wolfram/goldens/matrix-functions-v1.json");

#[derive(Debug, Deserialize)]
struct ComplexScalar {
    re: String,
    im: String,
}

#[derive(Debug, Deserialize)]
struct HermitianCase {
    u: Vec<ComplexScalar>,
    v: Vec<ComplexScalar>,
    dot_conj: ComplexScalar,
    dot_plain: ComplexScalar,
    norm2_u: String,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    schema: String,
    hermitian_3x3: HermitianCase,
}

fn parse(value: &ComplexScalar) -> Complex64 {
    Complex64::new(
        value.re.parse().expect("fixture value is a decimal"),
        value.im.parse().expect("fixture value is a decimal"),
    )
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture =
        serde_json::from_str(FIXTURE).expect("valid exact linear-algebra fixture");
    assert_eq!(fixture.schema, "sonium-qa.exact-linear-algebra.v1");
    fixture
}

#[test]
fn conjugate_dot_matches_wolfram() {
    let fixture = parse_fixture();
    let case = &fixture.hermitian_3x3;
    let u: Vec<Complex64> = case.u.iter().map(parse).collect();
    let v: Vec<Complex64> = case.v.iter().map(parse).collect();
    let expected = parse(&case.dot_conj);
    let actual = inner_product(&u, &v);
    assert!(
        (actual - expected).norm() <= 1e-12,
        "inner_product = {actual:?}, wolfram {expected:?}"
    );
}

#[test]
fn unconjugated_dot_matches_wolfram() {
    let fixture = parse_fixture();
    let case = &fixture.hermitian_3x3;
    let u: Vec<Complex64> = case.u.iter().map(parse).collect();
    let v: Vec<Complex64> = case.v.iter().map(parse).collect();
    let expected = parse(&case.dot_plain);
    let actual = dot_unconjugated(&u, &v);
    assert!(
        (actual - expected).norm() <= 1e-12,
        "dot_unconjugated = {actual:?}, wolfram {expected:?}"
    );
    // The two products genuinely differ on this fixture (conjugation is
    // observable, not a redundant code path).
    assert!(
        (parse(&case.dot_conj) - parse(&case.dot_plain)).norm() > 1.0,
        "fixture must distinguish conjugated from plain dot"
    );
}

#[test]
fn vector_norm_matches_wolfram() {
    let fixture = parse_fixture();
    let case = &fixture.hermitian_3x3;
    let u: Vec<Complex64> = case.u.iter().map(parse).collect();
    let expected: f64 = case.norm2_u.parse().expect("fixture value is a decimal");
    let actual = vector_norm(&u);
    assert!(
        (actual - expected).abs() <= 1e-12,
        "vector_norm = {actual:e}, wolfram {expected:e}"
    );
}

#[derive(Debug, Deserialize)]
struct AdjointCase {
    a: Vec<Vec<ComplexScalar>>,
    adjoint: Vec<Vec<ComplexScalar>>,
}

#[derive(Debug, Deserialize)]
struct MatrixFunctionsFixture {
    schema: String,
    adjoint_2x3: AdjointCase,
}

fn dense_complex(rows: &[Vec<ComplexScalar>]) -> DenseMatrix<Complex64> {
    let flat: Vec<Complex64> = rows.iter().flat_map(|row| row.iter().map(parse)).collect();
    DenseMatrix::from_row_major_vec(rows.len(), rows[0].len(), flat)
}

#[test]
fn adjoint_matches_wolfram() {
    let fixture: MatrixFunctionsFixture =
        serde_json::from_str(MATRIX_FUNCTIONS).expect("valid matrix-functions fixture");
    assert_eq!(fixture.schema, "sonium-qa.matrix-functions.v1");
    let case = &fixture.adjoint_2x3;
    let matrix = dense_complex(&case.a);
    let expected = dense_complex(&case.adjoint);
    let actual = matrix.adjoint();
    assert_eq!(actual.shape(), expected.shape());
    // Gaussian-integer input: transpose plus conjugation is exact in f64.
    assert_eq!(actual.as_slice(), expected.as_slice());
}
